<main class="auth-layout"><div class="auth-brand-panel"><a class="brand brand--light" href="<?= url() ?>"><img src="<?= photo(setting('logo')) ?>" width="55" height="55" alt=""><span><strong>SHREE JI</strong><small>GAS INDUSTRIES</small></span></a><div><span class="eyebrow">ACCOUNT RECOVERY</span><h1>A fresh start<br>for your workspace.</h1><p>Use the six-digit code from your email to choose a new password.</p></div></div><div class="auth-form-panel"><div class="auth-form"><span class="eyebrow">RESET PASSWORD</span><h2>Choose a new password.</h2><?php if($error): ?><div class="admin-alert admin-alert--error" role="alert"><?= e($error) ?></div><?php endif ?><?php if($valid): ?><form method="post" action="<?= url('admin/reset') ?>?token=<?= e(rawurlencode($token)) ?>"><?= csrfField() ?><input type="hidden" name="token" value="<?= e($token) ?>"><label for="resetOtp">Six-digit code</label><input id="resetOtp" name="otp" inputmode="numeric" pattern="[0-9]{6}" minlength="6" maxlength="6" required autocomplete="one-time-code"><label for="resetPassword">New password</label><input id="resetPassword" name="password" type="password" minlength="12" maxlength="72" required autocomplete="new-password"><label for="resetConfirm">Confirm password</label><input id="resetConfirm" name="confirm_password" type="password" minlength="12" maxlength="72" required autocomplete="new-password"><button class="btn btn-primary" type="submit">Reset password <?= icon('arrow-right-line') ?></button></form><?php else: ?><a class="btn btn-primary" href="<?= url('admin/forgot') ?>">Request a new code <?= icon('arrow-right-line') ?></a><?php endif ?><a class="auth-back" href="<?= url('admin/login') ?>"><?= icon('arrow-left-line') ?> Back to sign in</a></div></div></main>
